We consider a continuous optimization problem of the form
\begin{equation}\label{prob.opt}
  \min_{x \in \R^{m}}\ \phi(x),
\end{equation}

where $\phi$ is possibly non-convex, (twice-)continuously differentiable with Lipschitz continuous derivatives.
Neither function values $\phi(x)$, nor gradients $\nabla \phi(x)$ are assumed to be directly computable. Instead, given any $x \in \R^{m}$, it is assumed that stochastic estimates of $\phi(x)$, $\nabla \phi(x)$, and possibly $\nabla^2 \phi(x)$  can be computed, and these estimates may possess different levels of \emph{accuracy} and \emph{reliability} depending on the particular setting of interest.  


\begin{algorithm}
	\caption{~\textbf{Algorithmic Framework for Adaptive Stochastic Optimization}}
	\label{alg:generic_stochastic}

	{\bf 0. Initialization} 

	\vspace{0.5mm}

	\hspace{0.5cm} Choose $\mytheta \in (0,1)$, $\gamma\in (0, 1)$, $\alpha_{\max} \in (0,\infty)$, $x_0 \in \R^{m}$, and $\alpha_0 \in (0,\alpha_{\max}]$.  Set $k \gets 0$.
	\vspace{0.5mm}

	{\bf 1. Determine model and compute step}

	\vspace{0.5mm}

	\hspace{0.5cm} Construct a stochastic model $m_k$ of $\phi$ at $x_k$ using $f(x_k,\xi_{0,k})$, $g(x_k,\xi_{1,k})$, and (optionally) $H(x_k,\xi_{2,k})$ from \emph{probabilistic zeroth-, first-, and (optionally) second-order oracles}.  Compute $s_k(\alpha_k)$ such that the model reduction $m_k(x_k) - m_k(x_k+s_k(\alpha_k)) \geq 0$ is sufficiently large.
	\vspace{0.5mm}

	{\bf 2. Check for sufficient reduction}

	\vspace{0.5mm}

	\hspace{0.5cm} Set $x_k^+ \gets x_k + s_k(\alpha_k)$ and compute $f(x_k^+,\xi_{0,k}^+)$ as a stochastic estimate of $\phi(x_k^+)$ using a \emph{probabilistic zeroth-order oracle}.  Check if $ f(x_k,\xi_{0,k})- f(x_k^+,\xi_{0,k}^+)$ is sufficiently large (e.g., relative to the model reduction $m_k(x_k)-m_k(x_k^+)$) using a condition parameterized by~$\mytheta$.

	\vspace{0.5mm}
	{\bf 3. Successful iteration}

	\vspace{0.5mm}

	\hspace{0.5cm} If sufficient reduction has been attained (along with other potential requirements), then set $x_{k+1} \gets x_k^+ $ and $\alpha_{k+1} \gets \min\{\gamma^{-1}\alpha_k,\alpha_{\max}\}$.
	\vspace{0.5mm}

	{\bf 4. Unsuccessful iteration}

	\vspace{0.5mm}

	\hspace{0.5cm} Otherwise, set $x_{k+1} \gets x_k$ and $\alpha_{k+1} \gets \gamma \alpha_k$.
	\vspace{0.5mm}

	{\bf 5. Next iteration}

	\vspace{0.5mm}

	\hspace{0.5cm}  Set $k \gets k + 1$ and go to Step~1.
	\vspace{0.5mm}
\end{algorithm}

\begin{definition}{\bf Stochastic $j$th-order oracle.} Given an input  $x \in \R^{n}$ and the step size parameter $\alpha$, the oracle computes $\varphi_j(x,\xi_j)$, an estimate of the $j^{\mathrm{th}}$-order derivative $\nabla^j \phi(x)$. In all the algorithms we consider, $\|\varphi_j(x,\xi_j)- \nabla^j\phi(x)\|$ is assumed to be bounded by some quantity (which will be a function of  $\alpha$), with probability at least $1-\delta_j$.
%  where $\delta_j$ is an intrinsic value. 
   Here, $\xi_j$ is a random variable defined on probability space $(\Omega_j, {\cal F}_j, P_j)$ whose distribution depends on the input  $x$ and $\alpha$, and $\delta_j$ is intrinsic to the oracle.
%    and $\P_{\xi_j}$ denotes probability w.r.t.~that distribution. 
    The cost of the oracle is also a  function of $x$ and $\alpha$. 
  \end{definition}

Specifically, let $(X_k)_{k\geq 0}$ be the random iterates with realizations $x_k$, let $(G_k)_{k\geq 0}$ be the gradient estimates with realizations $g_k$, and let $(\mathcal{A}_k)_{k \geq 0}$ be the step size parameter values with realizations $\alpha_k$. The prior works that analyze different methods \rev{belonging to the framework of Algorithm~\ref{alg:generic_stochastic}}  define this stochastic process rigorously, with appropriate filtrations. Here for brevity, we will omit those details, as we do not use them in the analysis. 


\begin{defn}[Stopping time]
	For $\varepsilon > 0$, let $T_\varepsilon$ be the first time such that a specified optimality condition is satisfied. For all the settings considered in this paper,
	${T_\varepsilon}=\min\{k: \norm{\nabla \phi(x_k)} \leq \varepsilon\}$ if $\phi$ is non-convex, and ${T_\varepsilon}=\min\{k: \phi(x_k) - \inf_x \phi(x)  \leq \varepsilon\}$ if $\phi$ is strongly convex. We will refer to $T_\varepsilon$ as the \emph{stopping time} of the algorithm.
\end{defn}

\begin{assumption}
	[Properties of the stochastic process generated by the adaptive stochastic algorithm]
	\label{ass:alg_behave}
	The random sequence of parameters $\mathcal{A}_k$ generated by the algorithm satisfies the following: 
	\begin{itemize}
		\item[(i)] For all $k$, $\mathcal{A}_k \in \{\gamma \mathcal{A}_{k-1}, \min\{\amax, \gamma^{-1}\mathcal{A}_{k-1}\}\}$, and
		\item[(ii)] There exist constants $\bar\alpha > 0$, and $p>\frac 12$, such that \rev{for all iterations $k$,
%		 for all iterations  $k < T_\varepsilon$, if  $\mathcal{A}_k  \leq  \bar \alpha$ then
		$$\P(\mathcal{A}_{k+1} = \gamma^{-1} \mathcal{A}_{k} \mid \mathcal{F}_{k}, \, k < T_\varepsilon, \, \mathcal{A}_k  \leq  \bar \alpha ) \geq p.$$}
		Here, $\mathcal{F}_k$ denotes the filtration generated by the algorithm up to iteration $k$.
	\end{itemize}       

\end{assumption}

Throughout the remainder of this paper, we will use $q$ to denote $1-p$.


Let $\{\A_k\}_{k=0}^\infty$ denote the random sequence of parameter values (whose realization is $\{\alpha_k\}_{k=0}^\infty$), for  Algorithm \ref{alg:generic_stochastic}.  Let us assume, WLOG, that $\A_0 = \gamma^j \bar{\alpha}$, for some integer $j\leq0$.  (Recall here that $0 <\gamma < 1$.) Then we observe that $\mathcal{A}_k = \gamma^{\bar{Y}_k}\bar{\alpha}$,   where  $\{\bar{Y}_k\}_{k=0}^\infty$ is a random sequence of  integers, with $\bar{Y}_0 =j\leq 0$, which increases by one on every unsuccessful step, and decreases by one on every successful step. Moreover, by 
Assumption  \ref{ass:alg_behave}, whenever $k < T_\eps$ and $\bar{Y}_k \geq 0$, the probability that it decreases by one is at least $p$. Define $Y_k$ as follows:
\begin{equation}
\label{eq:Yk}
Y_k = \bar{Y}_k \quad \text{if $k \leq T_\eps$},
\qquad
Y_k = 
\begin{cases}
Y_{k-1} - 1 &\text{w.p. $p$} \\
Y_{k-1} + 1 &\text{w.p. $1-p$} 
\end{cases}
\quad
\text{if $k > T_\eps$.} 
\end{equation}

In other words, $Y_k$ follows the algorithm until $T_\eps$, and then behaves like a random walk with downward drift $p$ after $T_\eps$.
We now couple  $\{Y_k\}_{k=0}^\infty$  with a random walk $\{Z_k\}_{k=0}^\infty$ which stochastically dominates $Y_k$. 


Consider the following one-sided random walk $\{Z_k\}_{k=0}^\infty$, defined  on the non-negative integers. 
\begin{equation}
\label{eq:randwalk_update}
Z_0 = 0, \qquad Z_{k+1} = \begin{cases}
	Z_k +1, &\text{w.p. $1-p$,}\\
	Z_k-1, &\text{w.p. $p$, if $Z_k \geq 1$,}\\
	0, &\text{w.p. $p$, if $Z_k = 0$.}
\end{cases}
\end{equation}

\begin{defn}
Let $N(l, n)$ be the random variable that denotes the number of times $Z_k=l$  in the first $n$ steps of the random walk.  
%When $N(l, n)>0$, we say state $l$ is visited by the random walk. 
\end{defn}

By definition of $N(l, n)$, we have $N(l, n) > 0$ if and only if state $l$ is visited in the first $n$ steps of the random walk. The next proposition  upper bounds the probability that $N(l, n) > 0$. 


The cost of an oracle call may depend on the step size parameter $\alpha$ and the probability parameter $1-\delta$, thus we denote the cost by $\sc(\alpha, 1-\delta)$. 
We will use $\sc(\alpha)$ in the paper to simplify the notation because for all algorithms in the class, $\delta$ can be treated as a constant.
 Moreover, the cost of an oracle call is a non-increasing function of  $\alpha$ for all algorithms developed so far that fit into the framework. 


\begin{assumption}
	\label{ass:monotone}
%	\item For a fixed set of probability parameters of the stochastic oracles, the oracle costs of all the oracle calls at iteration $k$ only depend on the parameter $\alpha_k$. We assume $\sc(\alpha)$ increases as $\alpha$ decreases.
  $\sc(\alpha)$ is non-increasing in $\alpha$.
\end{assumption}

\begin{defn}[Total Oracle Complexity]
For a positive integer $n$, let $\SC(n)$ be the random variable which denotes the total oracle complexity of running the algorithm for $n$ iterations. In other words,
$$\SC(n) = \sum_{k=1}^n \sc(\mathcal{A}_k).$$
\end{defn}

