\begin{theorem}
\label{thm:stepsize_bound}
	Suppose Assumption \ref{ass:alg_behave} holds for Algorithm \ref{alg:generic_stochastic}. For any positive integer $n$, any $\omega  > 0$, with probability at least  $1 - n^{-\omega } - cn^{-(1+\omega )}$, we have 
	$$\text{either  $T_\eps < n$ ~or~ $\min_{1 \leq k \leq n} \alpha_k  
	\geq \rev{\alpha^*(n)} :=  \bar{\alpha}\gamma  \gamma^{{(1+\omega)\log_{1/2q} n}}
=\bar{\alpha}\gamma   n^{-{(1+\omega)\log_{1/2q} 1/\gamma}}$},$$ 	where $c = \frac{2\sqrt{pq}}{(1-2\sqrt{pq})^2}$ and $q = 1-p$.

% 	 In other words, with high probability the algorithm will not reach any step size smaller or equal to $ \gamma^{\ceil{(1+\nu )\log_{p/q} n}}\bar{\alpha}$ in the first $n$ steps. 
\end{theorem}

\begin{lemma}
	\label{lem:coupling_new}
	There exists a coupling between $Z_k$  and $Y_k$, where $Z_k$ stochastically dominates $Y_k$. 
\end{lemma}

\begin{proof}[Proof of Lemma \ref{lem:coupling_new}]
Initially, $Z_0=0$ and $Y_0 \leq 0$. For each $k$, we show how to update $Z_k$ to $Z_{k+1}$ according to how $Y_k$ changes to $Y_{k+1}$. We consider two cases depending on whether $k < T_\eps$ or $k \geq T_\eps$. 

\underline{Case 1: $k < T_\eps$}.
 If $Y_k\leq -1$, we update $Z_{k+1}$ from $Z_{k}$ according to \Cref{eq:randwalk_update}, independently of how $Y_k$ changes to $Y_{k+1}$. If $Y_k \geq 0$, then we first check if $Y_k$ increased or decreased. Let $p'$ be the probability that $Y_{k+1} = Y_k -1$ on this sample path. Since $Y_k \geq 0$, we know by \Cref{ass:alg_behave} that $p' \geq p$. Now, if $Y_{k+1} = Y_k + 1$, then we set $Z_{k+1} = Z_{k} + 1$. On the other hand, if $Y_{k+1} = Y_k - 1$, then we set $Z_{k+1} = Z_k + 1$ with probability $1 - \frac{p}{p'}$, and $Z_{k+1} = \max\{Z_k-1, 0\}$ with probability $\frac{p}{p'}$. Note that these probabilities are well-defined because $p' \geq p$. 

\underline{Case 2: $k \geq T_\eps$}. If $Y_{k+1} = Y_k + 1$, then set $Z_{k+1} = Z_{k}+1$. Otherwise, if $Y_{k+1} = Y_{k}-1$, then set $Z_{k+1} = \max\{Z_k-1, 0\}$. 

Observe that under this coupling, $Z_k \geq Y_k$ on every sample path. Moreover, $\{Z_k\}$ and $\{Y_k\}$ have the correct marginal distributions. For $Y_k$, this is easy to see, since it evolves according to its true distribution and we are constructing $Z_k$ from it. For $Z_k$, on any step with $k \geq T_\eps$, $Z_{k+1}$ evolves from $Z_k$ correctly according to \Cref{eq:randwalk_update} by construction. On a step with $k < T_\eps$ there are two cases: 1) $Y_k \leq -1$,  and 2) $Y_k \geq 0$. In the first case, the update from $Z_k$ to $Z_{k+1}$ clearly follows \Cref{eq:randwalk_update}. This is also true in the second case, since there the probability that $Z_{k}$ increases is $(1-p') + p'(1-\frac{p}{p'}) = 1-p$.

To summarize, we have exhibited a coupling between $\{Z_k\}$ and $\{Y_k\}$, under which $Z_k \geq Y_k$ on any sample path. 

%Thus, $\sA_k = \gamma^{Y_k}\bar{\alpha}$ the step size of the algorithm at iteration $k$, stochastically dominates $\gamma^{Z_k}\bar{\alpha}$.  Thus, to obtain a lower bound on the step sizes of the algorithm, it suffices to obtain an upper bound on the random walk $\{Z_k\}$. 
\end{proof}

\begin{prop}\label{prop:Fill}
	Let $q=1-p$. We have
%	$$\P(N(l,n) >0 ) \leq(n-l+1) \frac{1-(q / p)}{1-(q / p)^{l+1}}\left(\frac{q}{p}\right)^{l}  +
%	\frac{2 p \rev{2^l(pq)^{l/2}}}{(1-2 \sqrt{p q})^{2}}\left(\frac{q}{p}\right)^{(l+1) / 2}.$$
	$$\P(N(l,n) >0 ) \leq(n-l+1) \frac{1-(q / p)}{1-(q / p)^{l+1}}\left(\frac{q}{p}\right)^{l}  +
	\frac{2 \sqrt{pq}}{(1-2 \sqrt{p q})^{2}}(2q)^l.$$
\end{prop}

\begin{proof}
%	Let $q=1-p .$ 
%	Denote by $p_{l, N}$ the probability that state $l$ is reached in the first $N$ steps. Note that $p_{l, N} = \P(\mathcal{N}(l, N) > 0)$ by definition. 
	First, observe that $ \P({N}(l, n) > 0)$ remains unchanged if we change the state space from $\{0, 1,2, \ldots\}$ to $\{0, 1,2, \ldots, l\}$ and modify the walk to hold in state $l$ with probability $q$ (instead of moving from $l$ to $l+1$ with that probability). This defines a Markov chain on $\{0,1,2,\ldots, l\}$, and let $P$ be its transition matrix. Noting that $P_{0,l}^m$ is the probability that the Markov chain is in state $l$ at time $m$, we see that
	\begin{equation}
		\label{eq:subadd}
		\P(N(l,n) >0 ) \leq \sum_{m=l}^{n} P_{0, l}^{m}.
	\end{equation}

	The matrix $P$ is explicitly diagonalized in \cite{feller_book} (Section XVI.3). By $(3.16)$ in that section,
	\begin{equation}
		\label{eq:transprob}
		P_{0,l}^{m}=\frac{1-(q/p)}{1-(q / p)^{l+1}}\left(\frac{q}{p}\right)^{l} 
		-\frac{2 q}{l+1}\left(\frac{q}{p}\right)^{\frac{l-1}{2}} \sum_{r=1}^{l} \frac{\left[\sin \frac{\pi r}{l+1}\right]\left[\sin \frac{\pi rl}{l+1}\right]\left[2 \sqrt{pq} \cos \frac{\pi r}{l+1}\right]^{m}}{1-2 \sqrt{p q} \cos \frac{\pi r}{l+1}}.
	\end{equation}
	The absolute value of the sum appearing in (\ref{eq:transprob}) can of course be bounded above by
	$$
	\sum_{r=1}^{l} \frac{(2 \sqrt{p q})^{m}}{1-2 \sqrt{p q}}=l \frac{(2 \sqrt{p q})^{m}}{1-2 \sqrt{p q}}
	$$
	and this readily yields
	\begin{equation}
		\label{eq:fillprop_final}
		P_{0, l}^{m} \leq \frac{1-(q/p)}{1-(q / p)^{l+1}}\left(\frac{q}{p}\right)^{l} 
		+
		\frac{2 p}{1-2 \sqrt{p q}}\left(\frac{q}{p}\right)^{\frac{l+1}{2}}(2 \sqrt{p q})^{m}.
	\end{equation}
	Summing (\ref{eq:fillprop_final}) over $m=l, \ldots, n$ and using (\ref{eq:subadd}), we obtain the bound on $\P(N(l,n) >0 )$ claimed in the proposition.

\end{proof}

\begin{proof}[Proof of \Cref{thm:stepsize_bound}]
	Let $q=1-p$. By Proposition \ref{prop:Fill}, we have:
	$$\P(N(l,n) >0 ) \leq(n-l+1) \frac{1-(q / p)}{1-(q / p)^{l+1}}\left(\frac{q}{p}\right)^{l}  +
	\frac{2 \sqrt{pq}}{(1-2 \sqrt{p q})^{2}}(2q)^l.$$
	In other words,
	\begin{align*}
		\P(N(l,n) =0 ) &\geq 1-(n-l+1) \frac{1-(q / p)}{1-(q / p)^{l+1}}\left(\frac{q}{p}\right)^{l}  -
		\frac{2 \sqrt{pq}}{(1-2 \sqrt{p q})^{2}}(2q)^l \\
		&\geq 1- n \left(\frac{q}{p}\right)^{l}  -
		\frac{2 \sqrt{pq}}{(1-2 \sqrt{p q})^{2}}(2q)^l.
	\end{align*}
	Let $a>0$ be a parameter to be set later, and take $l=\ceil{a\log(n)}$. Then, the above inequality implies:
	\begin{align*}
	\P(N(l,n) =0 ) &\geq 1- n \left(\frac{q}{p}\right)^{a\log(n)}  -
	\frac{2 \sqrt{pq}}{(1-2 \sqrt{p q})^{2}}(2q)^{a\log(n)} \\
	&= 1- n^{1-a\log(\frac{p}{q})}  -
	\frac{2 \sqrt{pq}}{(1-2 \sqrt{p q})^{2}}n^{-a\log(1/(2q))}.
	\end{align*}
%	Note that $\left(\frac{q}{p}\right)^{\log_a(n)}=n^{\log_a(\frac{q}{p})}$, hence
%	$$\P(N(k,n) =0 )\geq 
