We consider a continuous optimization problem of the form
\begin{equation}\label{prob.opt}
  \min_{x \in \R^{m}}\ \phi(x),
\end{equation}

\begin{algorithm}
	\caption{~\textbf{Algorithmic Framework for Adaptive Stochastic Optimization}}
	\label{alg:generic_stochastic}

	{\bf 0. Initialization} 

	\vspace{0.5mm}

	\hspace{0.5cm} Choose $\mytheta \in (0,1)$, $\gamma\in (0, 1)$, $\alpha_{\max} \in (0,\infty)$, $x_0 \in \R^{m}$, and $\alpha_0 \in (0,\alpha_{\max}]$.  Set $k \gets 0$.
	\vspace{0.5mm}

	{\bf 1. Determine model and compute step}

	\vspace{0.5mm}

	\hspace{0.5cm} Construct a stochastic model $m_k$ of $\phi$ at $x_k$ using $f(x_k,\xi_{0,k})$, $g(x_k,\xi_{1,k})$, and (optionally) $H(x_k,\xi_{2,k})$ from \emph{probabilistic zeroth-, first-, and (optionally) second-order oracles}.  Compute $s_k(\alpha_k)$ such that the model reduction $m_k(x_k) - m_k(x_k+s_k(\alpha_k)) \geq 0$ is sufficiently large.
	\vspace{0.5mm}

	{\bf 2. Check for sufficient reduction}

	\vspace{0.5mm}

	\hspace{0.5cm} Set $x_k^+ \gets x_k + s_k(\alpha_k)$ and compute $f(x_k^+,\xi_{0,k}^+)$ as a stochastic estimate of $\phi(x_k^+)$ using a \emph{probabilistic zeroth-order oracle}.  Check if $ f(x_k,\xi_{0,k})- f(x_k^+,\xi_{0,k}^+)$ is sufficiently large (e.g., relative to the model reduction $m_k(x_k)-m_k(x_k^+)$) using a condition parameterized by~$\mytheta$.

	\vspace{0.5mm}
	{\bf 3. Successful iteration}

	\vspace{0.5mm}

	\hspace{0.5cm} If sufficient reduction has been attained (along with other potential requirements), then set $x_{k+1} \gets x_k^+ $ and $\alpha_{k+1} \gets \min\{\gamma^{-1}\alpha_k,\alpha_{\max}\}$.
	\vspace{0.5mm}

	{\bf 4. Unsuccessful iteration}

	\vspace{0.5mm}

	\hspace{0.5cm} Otherwise, set $x_{k+1} \gets x_k$ and $\alpha_{k+1} \gets \gamma \alpha_k$.
	\vspace{0.5mm}

	{\bf 5. Next iteration}

	\vspace{0.5mm}

	\hspace{0.5cm}  Set $k \gets k + 1$ and go to Step~1.
	\vspace{0.5mm}
\end{algorithm}

